CREATE FUNCTION public.lock_tenant_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid; target uuid; removing boolean:=false; BEGIN
 IF TG_TABLE_NAME='membership_roles' THEN target:=coalesce(NEW.membership_id,OLD.membership_id); SELECT organization_id INTO org FROM public.memberships WHERE id=target; removing:=TG_OP='DELETE' AND OLD.role='admin';
 ELSIF TG_TABLE_NAME='memberships' THEN org:=coalesce(NEW.organization_id,OLD.organization_id); target:=OLD.id; removing:=TG_OP='DELETE' OR (TG_OP='UPDATE' AND OLD.status='active' AND NEW.status<>'active');
 ELSE org:=coalesce(NEW.organization_id,OLD.organization_id); IF TG_OP='UPDATE' AND NEW.organization_id<>OLD.organization_id THEN RAISE EXCEPTION 'Organização do registro é imutável.'; END IF; END IF;
 PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
 IF removing AND EXISTS(SELECT 1 FROM public.memberships m JOIN public.membership_roles r ON r.membership_id=m.id WHERE m.id=target AND m.status='active' AND r.role='admin') AND NOT EXISTS(SELECT 1 FROM public.memberships m JOIN public.membership_roles r ON r.membership_id=m.id WHERE m.organization_id=org AND m.id<>target AND m.status='active' AND r.role='admin') THEN RAISE EXCEPTION 'A imobiliária precisa de um administrador ativo.'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.lock_tenant_mutation() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER membership_lock BEFORE INSERT OR UPDATE OR DELETE ON public.memberships FOR EACH ROW EXECUTE FUNCTION public.lock_tenant_mutation();
CREATE TRIGGER role_lock BEFORE INSERT OR UPDATE OR DELETE ON public.membership_roles FOR EACH ROW EXECUTE FUNCTION public.lock_tenant_mutation();
CREATE TRIGGER invitation_lock BEFORE INSERT OR UPDATE OR DELETE ON public.invitations FOR EACH ROW EXECUTE FUNCTION public.lock_tenant_mutation();
CREATE TRIGGER subscription_lock BEFORE INSERT OR UPDATE OR DELETE ON public.subscriptions FOR EACH ROW EXECUTE FUNCTION public.lock_tenant_mutation();
CREATE INDEX subscriptions_plan_idx ON public.subscriptions(plan_id);
CREATE INDEX invitations_creator_idx ON public.invitations(created_by);
CREATE INDEX audit_actor_idx ON public.audit_logs(actor_id);
CREATE FUNCTION public.platform_identity() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('id',auth.uid(),'email',(SELECT email FROM auth.users WHERE id=auth.uid()),'name',(SELECT full_name FROM public.profiles WHERE id=auth.uid()),'superadmin',public.is_superadmin(),'organizations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.id,'name',o.name,'roles',(SELECT jsonb_agg(r.role) FROM public.membership_roles r WHERE r.membership_id=m.id))) FROM public.memberships m JOIN public.organizations o ON o.id=m.organization_id WHERE m.user_id=auth.uid() AND m.status='active' AND o.status='active'),'[]'::jsonb)) WHERE auth.uid() IS NOT NULL $$;
REVOKE ALL ON FUNCTION public.platform_identity() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.platform_identity() TO authenticated;
CREATE OR REPLACE FUNCTION public.accept_invitation(hashed_token text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE invite public.invitations; member uuid; verified_email text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre para aceitar o convite.'; END IF; SELECT * INTO invite FROM public.invitations WHERE token_hash=hashed_token; IF NOT FOUND THEN RAISE EXCEPTION 'Convite inválido ou expirado.'; END IF; PERFORM 1 FROM public.organizations WHERE id=invite.organization_id AND status='active' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Imobiliária indisponível.'; END IF; SELECT * INTO invite FROM public.invitations WHERE id=invite.id FOR UPDATE; SELECT lower(email) INTO verified_email FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL; IF invite.status<>'pending' OR invite.expires_at<=now() OR invite.email IS DISTINCT FROM verified_email THEN RAISE EXCEPTION 'Convite inválido, expirado ou destinado a outro e-mail.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.subscriptions WHERE organization_id=invite.organization_id AND status='active') THEN RAISE EXCEPTION 'Assinatura indisponível.'; END IF; IF EXISTS(SELECT 1 FROM public.memberships WHERE organization_id=invite.organization_id AND user_id=auth.uid() AND status='active') THEN RAISE EXCEPTION 'Você já possui acesso ativo.'; END IF; UPDATE public.invitations SET status='accepted',accepted_by=auth.uid(),accepted_at=now() WHERE id=invite.id; INSERT INTO public.memberships(organization_id,user_id,status) VALUES(invite.organization_id,auth.uid(),'active') ON CONFLICT(organization_id,user_id) DO UPDATE SET status='active' RETURNING id INTO member; DELETE FROM public.membership_roles WHERE membership_id=member; INSERT INTO public.membership_roles(membership_id,role) SELECT member,unnest(invite.roles) ON CONFLICT DO NOTHING; PERFORM public.assert_capacity(invite.organization_id); INSERT INTO public.audit_logs(organization_id,actor_id,action,target_id) VALUES(invite.organization_id,auth.uid(),'invitation.accepted',invite.id); RETURN invite.organization_id; END $$;